begin;
select set_config('scene.qa_member',gen_random_uuid()::text,true),set_config('scene.qa_other',gen_random_uuid()::text,true),set_config('scene.qa_session',gen_random_uuid()::text,true),set_config('scene.qa_factor',gen_random_uuid()::text,true);
insert into auth.users(id,email,aud,role) select v::uuid,v||'@example.invalid','authenticated','authenticated' from unnest(array[current_setting('scene.qa_member'),current_setting('scene.qa_other')]) v;
insert into public.scene_members(user_id,email,display_name,role) select v::uuid,v||'@example.invalid','Worker test','member' from unnest(array[current_setting('scene.qa_member'),current_setting('scene.qa_other')]) v;
insert into auth.sessions(id,user_id,created_at,updated_at,aal) values(current_setting('scene.qa_session')::uuid,current_setting('scene.qa_member')::uuid,now(),now(),'aal1');
insert into public.scene_libraries(user_id,payload) select v::uuid,'{"entries":{"qa":{"title":{"id":"qa","name":"Fixture","kind":"series","tmdbId":999999999},"saved":true,"note":"Keep this","rating":4},"duplicate":{"title":{"id":"qa-duplicate","name":"Fixture","kind":"series","tmdbId":999999999},"saved":true}},"preferences":{},"services":{},"receipts":[]}'::jsonb from unnest(array[current_setting('scene.qa_member'),current_setting('scene.qa_other')]) v;
do $$declare rows jsonb;a timestamptz;uid uuid:=current_setting('scene.qa_member')::uuid;begin
 rows:=public.scene_claim_watchlist_checks();if (select count(*) from jsonb_array_elements(rows) x where x->>'user_id'=uid::text)<>1 then raise exception 'Duplicate canonical titles not deduplicated';end if;
 select attempted_at into a from public.scene_watchlist_snapshots where user_id=uid;
 rows:=public.scene_claim_watchlist_checks();if exists(select 1 from jsonb_array_elements(rows) x where x->>'user_id'=uid::text) then raise exception 'Duplicate concurrent lease';end if;
 perform public.scene_finish_watchlist_check(uid,'tmdb-series-999999999',a,'{"id":"qa","name":"Fixture","kind":"series","live":true,"dataSource":"tmdb","offers":[]}');
 if not exists(select 1 from public.scene_watchlist_snapshots where user_id=uid and checked_at is not null and not last_error) then raise exception 'Successful check missing';end if;
 if (select payload->'entries'->'qa'->>'note' from public.scene_libraries where user_id=uid)<>'Keep this' then raise exception 'Worker changed private library';end if;
 perform public.scene_finish_watchlist_check(uid,'tmdb-series-999999999',a,null);
 if not exists(select 1 from public.scene_watchlist_snapshots where user_id=uid and title is not null and checked_at is not null and last_error) then raise exception 'Failure discarded last good check';end if;
 update public.scene_libraries set payload=jsonb_set(payload,'{preferences,autoAvailability}','false') where user_id=uid;
 perform public.scene_claim_watchlist_checks();if exists(select 1 from public.scene_watchlist_snapshots where user_id=uid) then raise exception 'Opt-out retained queue';end if;
 update public.scene_libraries set payload=jsonb_set(payload,'{preferences,autoAvailability}','true') where user_id=uid;
 perform public.scene_claim_watchlist_checks();select attempted_at into a from public.scene_watchlist_snapshots where user_id=uid;
 update public.scene_libraries set payload=jsonb_set(payload,'{entries}','{}') where user_id=uid;
 perform public.scene_finish_watchlist_check(uid,'tmdb-series-999999999',a,'{"id":"qa","name":"Fixture","kind":"series","live":true,"dataSource":"tmdb","offers":[]}');
 if exists(select 1 from public.scene_watchlist_snapshots where user_id=uid and checked_at is not null) then raise exception 'Removed title accepted late result';end if;
 perform public.scene_claim_watchlist_checks();if exists(select 1 from public.scene_watchlist_snapshots where user_id=uid) then raise exception 'Removed title retained queue';end if;
end$$;
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('scene.qa_member'),'session_id',current_setting('scene.qa_session'),'role','authenticated','aal','aal1')::text,true);
set local role authenticated;
do $$begin
 if exists(select 1 from public.scene_watchlist_snapshots where user_id<>auth.uid()) then raise exception 'Cross-account snapshots exposed';end if;
 begin perform public.scene_watchlist_worker_config();raise exception 'Worker secrets exposed';exception when insufficient_privilege then null;end;
 begin perform public.scene_claim_watchlist_checks();raise exception 'Queue exposed';exception when insufficient_privilege then null;end;
 begin perform public.scene_configure_watchlist_worker(repeat('x',30));raise exception 'Secret write exposed';exception when insufficient_privilege then null;end;
 begin insert into public.scene_watchlist_snapshots(user_id,title_key,hint) values(auth.uid(),'bad','{}');raise exception 'Member wrote snapshot';exception when insufficient_privilege then null;end;
 begin insert into public.scene_departures(id,title) values('bad','Bad');raise exception 'Member wrote expiry';exception when insufficient_privilege then null;end;
end$$;
reset role;
insert into public.scene_watchlist_snapshots(user_id,title_key,hint) values(current_setting('scene.qa_member')::uuid,'own','{}');
insert into auth.mfa_factors(id,user_id,friendly_name,factor_type,status,created_at,updated_at,secret) values(current_setting('scene.qa_factor')::uuid,current_setting('scene.qa_member')::uuid,'Fixture','totp','verified',now(),now(),'fixture');
set local role authenticated;
do $$begin if exists(select 1 from public.scene_watchlist_snapshots) then raise exception 'MFA bypass';end if;end$$;
reset role;
rollback;
select 'PASS: queue deduplication, leases, snapshots, opt-out, removal, private fields, account isolation, client write denial, worker-secret denial and MFA' as result;
